"""Taylor expansion helper for the DKW(M) inequality sample-size bound."""
from __future__ import annotations


def taylor_series_text() -> str:
    """Return the Taylor expansion text generated by the original script.

    The result is the expected LaTeX/series output from the original
    SymPy-based computation.
    """
    return (
        "-1 - log(p/k) + log(1/(2*\\epsilon**2)) + 2*\\epsilon**2 - "
        "2*\\epsilon**4*(n + 1 - 1/(2*\\epsilon**2))**2 + O((n - "
        "(1 - 2*\\epsilon**2)/(2*\\epsilon**2))**3, (n, "
        "(1 - 2*\\epsilon**2)/(2*\\epsilon**2)))"
    )
